test.describe("Repositories: editor statusline stays a single line", () => {
  test.beforeEach(async ({ context }) => {
    await context.route("**/api.github.com/**", (route) => route.abort());
  });

  test("statusline height is identical for a short breadcrumb and a long nested-path breadcrumb", async ({
    page,
  }) => {
    // Viewport narrowed just enough to force the long breadcrumb to overflow (below 900px the desktop keyboard-listener gate never attaches) — only the breadcrumb's own ellipsis/nowrap CSS keeps this single-line.
    await page.setViewportSize({ width: 900, height: 700 });
    await gotoReady(page, "/repositories");
    await openRepoTree(page, "daily-tech-digest");

    // Short baseline: "daily-tech-digest › README.md" at depth 0 — needs disambiguating since daily-tech-digest also has a nested "site/README.md".
    await treeRow(page, "README.md", 0).click();
    await page.keyboard.press("2");
    await page.keyboard.press("Enter");
    const statusline = page.locator('[data-testid="editor-statusline"]');
    await expect(statusline).toBeVisible();
    const shortHeight = (await statusline.boundingBox())!.height;

    await page.keyboard.press(":");
    await page.keyboard.type("q");
    await page.keyboard.press("Enter");
    await expect(page.locator('[data-testid="editor-scroller"]')).toHaveCount(0);

    // Long breadcrumb: Data-Structures-And-Algorithms' longest real path (read off disk so it can't drift) — its 61-char filename alone exceeds the available flex space at any allowed viewport width, forcing overflow reliably.
    const longFileName = "avaerage_salary_excluding_the_minimum_and_maximum_salary.py";
    const longPath = `Sorting Algorithms/${longFileName}`;
    expect(fileLines(`Data-Structures-And-Algorithms/${longPath}`).length).toBeGreaterThan(0);
    await openRepoTree(page, "Data-Structures-And-Algorithms");
    await treeRow(page, longFileName).click();
    await page.keyboard.press("2");
    await page.keyboard.press("Enter");
    await expect(statusline).toBeVisible();
    const longHeight = (await statusline.boundingBox())!.height;

    // Equal height (within a hairline of rounding) proves the long-path
    // breadcrumb truncated/ellipsized instead of wrapping onto a 2nd line.
    expect(Math.abs(longHeight - shortHeight)).toBeLessThan(2);
  });
});
